const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=1000,H=500,C=50,COLS=20,ROWS=10;
const defs=[
 {id:'generator',name:'Generator',desc:'Charge +1.5 / sec',cost:65,power:0,tag:'⚡',color:'#83d9e5'},
 {id:'miner',name:'Alloy Miner',desc:'Alloy +1.6 / sec',cost:55,power:.25,tag:'◈',color:'#ffcf74'},
 {id:'forge',name:'Hero Forge',desc:'Prints a hero every 7 sec',cost:90,power:.65,tag:'⬡',color:'#9ce7be'},
 {id:'barracks',name:'Barracks',desc:'Hero capacity +6 · +10% speed',cost:100,power:.35,tag:'▦',color:'#c19bff'},
 {id:'turret',name:'Bolt Turret',desc:'Auto-fires at nearby hostiles',cost:80,power:.5,tag:'⌖',color:'#ff816e'},
 {id:'prism',name:'Prism Cannon',desc:'Long range · heavy damage',cost:145,power:1,tag:'✧',color:'#f492d0'},
 {id:'wall',name:'Aegis Wall',desc:'Absorbs hits · blocks nothing',cost:35,power:0,tag:'▥',color:'#899ba0'},
 {id:'repair',name:'Repair Bay',desc:'Repairs core +0.35% / sec',cost:115,power:.45,tag:'✚',color:'#a2e8bf'},
 {id:'lab',name:'Research Lab',desc:'Earns 1 data every 8 sec',cost:135,power:.55,tag:'⌘',color:'#c19bff'},
 {id:'recycler',name:'Recycler',desc:'Salvage +0.4 alloy / sec',cost:75,power:.3,tag:'⟳',color:'#e4a77b'}
];
const heroTypes=[
 {name:'Dash',shape:'tri',color:'#a2e8bf',hp:58,damage:13,rate:.86,speed:30,range:105},
 {name:'Bulwark',shape:'square',color:'#ffcf74',hp:150,damage:10,rate:1.15,speed:18,range:90},
 {name:'Pulse',shape:'circle',color:'#83d9e5',hp:76,damage:9,rate:.72,speed:22,range:140},
 {name:'Ranger',shape:'diamond',color:'#f492d0',hp:62,damage:20,rate:1.35,speed:19,range:205},
 {name:'Nova',shape:'star',color:'#c19bff',hp:80,damage:16,rate:1.1,speed:24,range:130},
 {name:'Warden',shape:'hex',color:'#ff9b72',hp:115,damage:18,rate:1.3,speed:17,range:110}
];
let state;let last=performance.now(),acc=0,selected=null,mouse={x:0,y:0},toastTimeout,paused=false,speed=1;
function fresh(){return {alloy:180,charge:20,maxCharge:40,core:100,wave:0,time:0,waveClock:20,spawning:false,spawnLeft:0,spawnTimer:0,heroTimer:7,heroes:[],enemies:[],bullets:[],particles:[],buildings:[],kills:0,data:0,over:false,log:[],elapsed:0};}
state=fresh();
const buildList=document.getElementById('buildList');
for(const d of defs){const b=document.createElement('button');b.className='build-card';b.dataset.id=d.id;b.innerHTML=`<span class="bicon" style="color:${d.color}"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2"><path d="${shapePath(d.id)}"/></svg></span><span class="bcopy"><span class="bname">${d.name}</span><span class="bdesc">${d.desc}</span></span><span class="cost">${d.cost} ◈</span>`;b.onclick=()=>{selected=selected===d.id?null:d.id;renderCards();document.getElementById('tip').textContent=selected?`PLACE ${d.name.toUpperCase()} · CLICK AN EMPTY TILE`:'SELECT A STRUCTURE · CLICK AN EMPTY TILE TO BUILD';};buildList.appendChild(b);}
function shapePath(id){return ({generator:'M16 3 28 9v14l-12 6-12-6V9L16 3Z M16 3v13l12-7M16 16 4 9m12 7v13',miner:'M6 22 16 5l10 17H6Z M16 12v5m0 3v.1',forge:'M16 3 28 10v12l-12 7L4 22V10L16 3Z M11 17l3 3 7-8',barracks:'M5 5h22v22H5z M5 12h22M12 5v7m8-7v7m-8 5v10m8-10v10',turret:'M16 4 19 12 28 13 21 19 23 28 16 23 9 28 11 19 4 13 13 12 16 4Z M16 15v7',prism:'M16 3 29 16 16 29 3 16 16 3Z M16 9v14m-7-7h14',wall:'M5 5h22v22H5z M5 12h22M12 5v7m8-7v7m-8 5v10m8-10v10',repair:'M13 4h6v9h9v6h-9v9h-6v-9H4v-6h9z',lab:'M7 5h18v22H7z M12 11h8m-8 5h8m-8 5h5',recycler:'M25 14a9 9 0 0 0-16-5L6 12m0-7v7h7m-6 6a9 9 0 0 0 16 5l3-3m0 7v-7h-7'})[id]||'M4 4h24v24H4z';}
function renderCards(){document.querySelectorAll('.build-card').forEach(b=>b.classList.toggle('selected',b.dataset.id===selected));}
function log(msg){state.log.unshift(msg);state.log=state.log.slice(0,3);document.getElementById('log').innerHTML=state.log.map(x=>`<span>${x}</span>`).join('');}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),1500);}
function placeBuilding(c,r){if(c<4||c>14){toast('Build within the marked factory zone');return;}if(state.buildings.some(b=>b.c===c&&b.r===r)){toast('Tile already occupied');return;}const d=defs.find(x=>x.id===selected);if(!d)return;if(state.alloy<d.cost){toast('Not enough alloy');return;}state.alloy-=d.cost;const b={...d,c,r,hp:d.id==='wall'?180:100,maxHp:d.id==='wall'?180:100,timer:0,fire:0};state.buildings.push(b);if(d.id==='generator'){state.maxCharge+=15;state.charge=Math.min(state.maxCharge,state.charge+4);}log(`${d.name} constructed`);toast(`${d.name} online`);selected=null;renderCards();document.getElementById('tip').textContent='SELECT A STRUCTURE · CLICK AN EMPTY TILE TO BUILD';}
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;});
canvas.addEventListener('pointerdown',e=>{if(state.over)return;const c=Math.floor(mouse.x/C),r=Math.floor(mouse.y/C);if(selected){placeBuilding(c,r);return;}const b=state.buildings.find(o=>o.c===c&&o.r===r);if(b){const d=defs.find(x=>x.id===b.id);if(state.alloy>=Math.ceil(d.cost*.45)){state.alloy+=Math.ceil(d.cost*.45);state.buildings=state.buildings.filter(x=>x!==b);if(b.id==='generator')state.maxCharge=Math.max(40,state.maxCharge-15);log(`${b.name} dismantled · alloy recovered`);toast('Structure salvaged');}else toast('Need alloy to salvage');}});
function addHero(index){if(state.heroes.length>=heroCap())return false;const t=heroTypes[index%heroTypes.length];state.heroes.push({type:t,x:164+Math.random()*18,y:120+Math.random()*260,hp:t.hp,maxHp:t.hp,attack:Math.random()*.5,walk:0,level:Math.max(1,Math.floor((state.wave-1)/5)+1)});return true;}
function heroCap(){return 12+state.buildings.filter(b=>b.id==='barracks').length*6;}
function startWave(){state.wave++;state.spawning=true;state.spawnLeft=4+state.wave*2;state.spawnTimer=.4;state.waveClock=12+Math.max(0,state.wave-1)*1.3;log(`Wave ${String(state.wave).padStart(2,'0')} inbound · ${state.spawnLeft} shapes detected`);document.getElementById('status').textContent='HOSTILES DETECTED';}
function spawnEnemy(){const wave=state.wave;const kind=Math.floor(Math.random()*Math.min(3+Math.floor(wave/2),6));const types=[
 {name:'Nib',shape:'tri',color:'#ff816e',hp:36,damage:9,speed:18,reward:7,r:9},
 {name:'Shard',shape:'diamond',color:'#f6a56e',hp:65,damage:12,speed:13,reward:10,r:11},
 {name:'Brute',shape:'square',color:'#e16b71',hp:145,damage:20,speed:7,reward:18,r:14},
 {name:'Wisp',shape:'circle',color:'#c887e5',hp:70,damage:11,speed:16,reward:13,r:10},
 {name:'Reaver',shape:'hex',color:'#e75058',hp:105,damage:17,speed:12,reward:16,r:13},
 {name:'Titan',shape:'star',color:'#ffb45e',hp:280,damage:31,speed:5,reward:32,r:17}
];const t=types[kind];const scale=1+(wave-1)*.19;const lane=1+Math.floor(Math.random()*8);state.enemies.push({type:t,x:965+Math.random()*20,y:lane*C+25,hp:t.hp*scale,maxHp:t.hp*scale,attack:0,slow:0});}
function nearestEnemy(x,y,range){let best=null,dist=range;for(const e of state.enemies){const d=Math.hypot(e.x-x,e.y-y);if(d<dist){dist=d;best=e;}}return best;}
function damageEnemy(e,n,x,y,color){if(!state.enemies.includes(e))return;e.hp-=n;state.particles.push({x,y,vx:(Math.random()-.5)*35,vy:(Math.random()-.5)*35,life:.25,color});if(e.hp<=0){state.enemies=state.enemies.filter(a=>a!==e);state.kills++;state.alloy+=e.type.reward;state.charge=Math.min(state.maxCharge,state.charge+.35);state.particles.push({x:e.x,y:e.y,vx:0,vy:-25,life:.55,color:'#ffcf74',text:`+${e.type.reward}`});if(state.kills%5===0)log(`Salvaged ${e.type.reward} alloy · ${state.kills} total kills`);}}
function tick(dt){if(state.over||paused)return;dt*=speed;state.elapsed+=dt;state.time+=dt;
 let gen=.18,draw=.12;for(const b of state.buildings){if(b.id==='generator')gen+=1.5;else draw+=b.power;}
 state.charge=Math.min(state.maxCharge,state.charge+gen*dt);const powered=state.charge>0.02;if(powered)state.charge=Math.max(0,state.charge-draw*dt);let efficiency=powered?1:0;
 if(efficiency){for(const b of state.buildings){if(b.id==='miner')state.alloy+=1.6*dt;else if(b.id==='recycler')state.alloy+=.4*dt;else if(b.id==='lab'){b.timer+=dt;if(b.timer>=8){b.timer-=8;state.data++;state.alloy+=4;}}else if(b.id==='repair'){state.core=Math.min(100,state.core+.35*dt);}}}
 state.heroTimer-=dt;if(state.heroTimer<=0){state.heroTimer=10;addHero(0);}
 for(const b of state.buildings){b.timer+=dt;if(efficiency&&b.id==='forge'&&b.timer>=7){b.timer=0;if(addHero((state.wave+b.c+b.r+Math.floor(Math.random()*heroTypes.length))%heroTypes.length))log('New hero printed at the forge');}if(efficiency&&(b.id==='turret'||b.id==='prism')){b.fire-=dt;const range=b.id==='turret'?235:350;const e=nearestEnemy(b.c*C+25,b.r*C+25,range);if(e&&b.fire<=0){b.fire=b.id==='turret'?.95:1.65;state.bullets.push({x:b.c*C+25,y:b.r*C+25,target:e,speed:b.id==='turret'?370:440,damage:b.id==='turret'?27:72,color:b.color});}}}
 if(state.wave===0){state.waveClock-=dt;if(state.waveClock<=0)startWave();}else if(state.spawning){state.spawnTimer-=dt;if(state.spawnLeft>0&&state.spawnTimer<=0){spawnEnemy();state.spawnLeft--;state.spawnTimer=Math.max(.65,2.4-state.wave*.055);}if(state.spawnLeft===0&&state.enemies.length===0){state.spawning=false;state.waveClock=9;document.getElementById('status').textContent='SYSTEM ONLINE';state.alloy+=20+state.wave*2;log(`Wave ${state.wave} cleared · bonus alloy awarded`);}}else{state.waveClock-=dt;if(state.waveClock<=0)startWave();}
 for(const h of state.heroes){h.attack-=dt;const target=nearestEnemy(h.x,h.y,h.type.range);if(target){if(h.attack<=0){h.attack=h.type.rate;state.bullets.push({x:h.x,y:h.y,target,speed:500,damage:h.type.damage*h.level,color:h.type.color});}if(Math.abs(target.x-h.x)>h.type.range*.72)h.x+=Math.min(h.type.speed*dt,Math.max(0,target.x-h.x-h.type.range*.7));}else h.x=Math.min(460,h.x+h.type.speed*dt);}
 for(const e of [...state.enemies]){if(!state.enemies.includes(e))continue;e.x-=e.type.speed*dt;const b=state.buildings.filter(a=>a.id==='wall'&&Math.abs(a.c*C+25-e.x)<18&&Math.abs(a.r*C+25-e.y)<30).sort((a,b)=>Math.abs(a.c*C+25-e.x)-Math.abs(b.c*C+25-e.x))[0];if(b){e.attack-=dt;if(e.attack<=0){e.attack=.9;b.hp-=e.type.damage;if(b.hp<=0){state.buildings=state.buildings.filter(x=>x!==b);log('Aegis wall breached');}}}if(e.x<80){e.attack-=dt;if(e.attack<=0){e.attack=.7;state.core-=e.type.damage/3;state.particles.push({x:68,y:e.y,vx:-15,vy:0,life:.4,color:'#ff816e'});if(state.core<=0){state.core=0;endGame();}}}}
 for(const p of state.bullets){if(!state.enemies.includes(p.target))continue;const dx=p.target.x-p.x,dy=p.target.y-p.y,d=Math.hypot(dx,dy),step=p.speed*dt;if(d<step+8){damageEnemy(p.target,p.damage,p.target.x,p.target.y,p.color);p.dead=true;}else{p.x+=dx/d*step;p.y+=dy/d*step;}}
 state.bullets=state.bullets.filter(p=>!p.dead&&state.enemies.includes(p.target));for(const p of state.particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;}state.particles=state.particles.filter(p=>p.life>0);
 updateUI();}
function endGame(){state.over=true;document.getElementById('status').textContent='CORE LOST';document.getElementById('finalScore').textContent=`You survived ${state.wave} wave${state.wave===1?'':'s'} · ${state.kills} hostile shapes neutralized · ${Math.floor(state.elapsed)} seconds online.`;document.getElementById('endModal').style.display='grid';}
function updateUI(){document.getElementById('alloy').textContent=Math.floor(state.alloy);document.getElementById('charge').innerHTML=`${Math.floor(state.charge)} <small>/ ${Math.floor(state.maxCharge)}</small>`;document.getElementById('wave').innerHTML=`${String(Math.max(1,state.wave)).padStart(2,'0')} <small>${state.wave===0?'PREP':state.spawning?'LIVE':'NEXT'}</small>`;document.getElementById('heroes').innerHTML=`${state.heroes.length} <small>/ ${heroCap()}</small>`;document.getElementById('core').innerHTML=`${Math.ceil(state.core)} <small>%</small>`;document.getElementById('clock').textContent=`${String(Math.floor(state.elapsed/60)).padStart(2,'0')}:${String(Math.floor(state.elapsed%60)).padStart(2,'0')}`;const remain=state.wave===0?state.waveClock:state.spawning?state.spawnLeft*2.4+state.enemies.length*.7:state.waveClock;document.getElementById('waveTimer').textContent=state.wave===0?`WAVE IN ${Math.ceil(state.waveClock)}s`:state.spawning?`${state.spawnLeft} SPAWNING`:`NEXT WAVE ${Math.ceil(state.waveClock)}s`;document.getElementById('enemiesLeft').textContent=`${state.enemies.length+(state.spawning?state.spawnLeft:0)} HOSTILES`;document.getElementById('waveProgress').style.width=`${Math.max(0,Math.min(100,100-remain/(state.wave===0?20:30)*100))}%`;document.getElementById('roster').innerHTML=state.heroes.length?heroTypes.map(t=>{const n=state.heroes.filter(h=>h.type.name===t.name).length;return n?`<span class="unit-chip" style="border-color:${t.color}55">${t.name} <b>×${n}</b></span>`:''}).join(''):'<span class="unit-chip">No heroes deployed</span>';}

function polygon(x,y,r,n,rot=-Math.PI/2){ctx.beginPath();for(let i=0;i<n;i++){const a=rot+i*Math.PI*2/n;const px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();}
function drawShape(x,y,r,shape,color,glow=false){ctx.save();ctx.translate(x,y);ctx.fillStyle=color;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.shadowColor=glow?color:'transparent';ctx.shadowBlur=glow?13:0;
 if(shape==='tri')polygon(0,0,r,3);else if(shape==='square')polygon(0,0,r,4,Math.PI/4);else if(shape==='diamond')polygon(0,0,r,4);else if(shape==='hex')polygon(0,0,r,6);else if(shape==='star'){ctx.beginPath();for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.48:r;let px=Math.cos(a)*rr,py=Math.sin(a)*rr;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();}else{ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);}
 ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#132023';ctx.beginPath();ctx.arc(-r*.22,-r*.1,Math.max(1.7,r*.12),0,Math.PI*2);ctx.arc(r*.22,-r*.1,Math.max(1.7,r*.12),0,Math.PI*2);ctx.fill();ctx.strokeStyle='#132023';ctx.lineWidth=Math.max(1.2,r*.08);ctx.beginPath();ctx.moveTo(-r*.2,r*.27);ctx.quadraticCurveTo(0,r*.42,r*.2,r*.27);ctx.stroke();ctx.restore();}
function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#151f22';ctx.fillRect(0,0,W,H);
 // subtle workshop lights and floor grid
 const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#1a2729');bg.addColorStop(.55,'#172124');bg.addColorStop(1,'#11191c');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
 for(let r=0;r<ROWS;r++){for(let c=0;c<COLS;c++){const x=c*C,y=r*C;ctx.fillStyle=(r+c)%2?'#ffffff03':'#00000006';ctx.fillRect(x,y,C,C);ctx.strokeStyle='#82999813';ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,C,C);}}
 // build zone
 ctx.fillStyle='#9ce7be08';ctx.fillRect(4*C,0,11*C,H);ctx.strokeStyle='#9ce7be19';ctx.setLineDash([5,6]);ctx.strokeRect(4*C+1,1,11*C-2,H-2);ctx.setLineDash([]);
 ctx.fillStyle='#a2e8bf55';ctx.font='9px DM Mono,monospace';ctx.fillText('FACTORY BUILD ZONE',4*C+10,15);
 // lane markings
 for(let r=0;r<ROWS;r++){ctx.fillStyle=r%2?'#81979609':'#94ad9f0b';ctx.fillRect(0,r*C+24,W,2);}
 // core complex
 ctx.fillStyle='#202e30';ctx.fillRect(9,113,126,274);ctx.strokeStyle='#55706a';ctx.lineWidth=1;ctx.strokeRect(9.5,113.5,125,273);ctx.fillStyle='#152022';ctx.fillRect(20,125,104,248);ctx.strokeStyle='#364b48';ctx.strokeRect(20.5,125.5,103,247);
 ctx.fillStyle='#85ddac';ctx.font='9px DM Mono,monospace';ctx.fillText('CORE // 01',31,144);
 // core vertical health gauge
 ctx.fillStyle='#334342';ctx.fillRect(30,153,6,197);ctx.fillStyle=state.core>40?'#9ce7be':'#ff816e';ctx.fillRect(30,153+197*(1-state.core/100),6,197*state.core/100);
 ctx.save();ctx.shadowColor='#9ce7be';ctx.shadowBlur=16;ctx.strokeStyle='#9ce7be';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(70,199);ctx.lineTo(99,216);ctx.lineTo(99,250);ctx.lineTo(70,267);ctx.lineTo(41,250);ctx.lineTo(41,216);ctx.closePath();ctx.stroke();ctx.restore();ctx.fillStyle='#9ce7be';ctx.beginPath();ctx.arc(70,233,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a7b6b0';ctx.font='8px DM Mono,monospace';ctx.fillText('FOUNDATION CORE',40,292);ctx.fillStyle='#778b88';ctx.fillText('HERO PRINT BAY',43,337);ctx.fillStyle='#2d4241';ctx.fillRect(44,345,52,5);ctx.fillStyle='#9ce7be';ctx.fillRect(44,345,52*Math.min(1,1-state.heroTimer/10),5);
 // approach alert edge
 ctx.fillStyle='#ff816e14';ctx.fillRect(940,0,60,H);ctx.fillStyle='#ff816e';ctx.font='9px DM Mono,monospace';ctx.fillText('VOID',954,16);
 // selection ghost
 if(selected){const c=Math.floor(mouse.x/C),r=Math.floor(mouse.y/C);if(c>=0&&c<COLS&&r>=0&&r<ROWS){ctx.fillStyle='#9ce7be18';ctx.fillRect(c*C+2,r*C+2,C-4,C-4);ctx.strokeStyle='#9ce7beaa';ctx.setLineDash([4,4]);ctx.strokeRect(c*C+2.5,r*C+2.5,C-5,C-5);ctx.setLineDash([]);const d=defs.find(x=>x.id===selected);drawStructure({id:d.id,c,r,hp:100,maxHp:100},true);}}else if(mouse.x>0&&mouse.x<W){const b=state.buildings.find(o=>o.c===Math.floor(mouse.x/C)&&o.r===Math.floor(mouse.y/C));if(b){ctx.fillStyle='#ffffff0b';ctx.fillRect(b.c*C+1,b.r*C+1,C-2,C-2);}}
 for(const b of state.buildings)drawStructure(b,false);
 // projectiles
 for(const p of state.bullets){ctx.save();ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();ctx.restore();}
 for(const h of state.heroes){drawShape(h.x,h.y,10,h.type.shape,h.type.color,true);if(h.level>1){ctx.fillStyle='#fff';ctx.font='8px DM Mono,monospace';ctx.fillText('+'+h.level,h.x+10,h.y-8);}if(h.hp<h.maxHp){ctx.fillStyle='#101719';ctx.fillRect(h.x-10,h.y+13,20,3);ctx.fillStyle=h.type.color;ctx.fillRect(h.x-10,h.y+13,20*Math.max(0,h.hp/h.maxHp),3);}}
 for(const e of state.enemies){drawShape(e.x,e.y,e.type.r,e.type.shape,e.type.color,true);ctx.fillStyle='#101719';ctx.fillRect(e.x-13,e.y-e.type.r-8,26,3);ctx.fillStyle='#ff8a75';ctx.fillRect(e.x-13,e.y-e.type.r-8,26*Math.max(0,e.hp/e.maxHp),3);}
 for(const p of state.particles){ctx.globalAlpha=Math.max(0,p.life/.55);if(p.text){ctx.fillStyle=p.color;ctx.font='bold 11px DM Mono,monospace';ctx.fillText(p.text,p.x,p.y);}else{ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,2.4,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
 // tiny map location and heroes count on base
 ctx.fillStyle='#a4b9ae';ctx.font='9px DM Mono,monospace';ctx.fillText(`${state.heroes.length} UNITS`,38,368);
}
function drawStructure(b,ghost){const x=b.c*C,y=b.r*C;const color=defs.find(d=>d.id===b.id)?.color||'#9ce7be';ctx.save();if(ghost)ctx.globalAlpha=.55;ctx.fillStyle='#202d30';ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.fillRect(x+5,y+5,40,40);ctx.strokeRect(x+5.5,y+5.5,39,39);
 ctx.fillStyle=color;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 19px sans-serif';ctx.fillText(defs.find(d=>d.id===b.id)?.tag||'⬡',x+25,y+24);
 if(!ghost){ctx.fillStyle='#101719';ctx.fillRect(x+9,y+44,32,2);ctx.fillStyle=b.hp/b.maxHp>.5?'#9ce7be':'#ff816e';ctx.fillRect(x+9,y+44,32*Math.max(0,b.hp/b.maxHp),2);}
